class Solution {
    public int compress(char[] chars) {
        int write = 0;
        int read = 0;
        while (read < chars.length) {
            char current = chars[read];
            int count = 0;
            while (read < chars.length && chars[read] == current) {
                read++;
                count++;
            }

            chars[write++] = current;
            if (count > 1) {
                String digits = Integer.toString(count);
                for (int i = 0; i < digits.length(); i++) {
                    chars[write++] = digits.charAt(i);
                }
            }
        }
        return write;
    }
}

class Solution {
    public int compress(char[] chars) {
        int write = 0;
        int read = 0;
        while (read < chars.length) {
            char current = chars[read];
            int start = read;
            while (read < chars.length && chars[read] == current) {
                read++;
            }

            chars[write++] = current;
            int count = read - start;
            if (count > 1) {
                int digitStart = write;
                while (count > 0) {
                    chars[write++] = (char) ('0' + count % 10);
                    count /= 10;
                }
                reverse(chars, digitStart, write - 1);
            }
        }
        return write;
    }

    private void reverse(char[] chars, int left, int right) {
        while (left < right) {
            char temp = chars[left];
            chars[left] = chars[right];
            chars[right] = temp;
            left++;
            right--;
        }
    }
}

class Solution {
    public int compress(char[] chars) {
        int write = 0;
        int read = 0;
        while (read < chars.length) {
            char current = chars[read];
            int count = 0;
            while (read < chars.length && chars[read] == current) {
                read++;
                count++;
            }
            chars[write++] = current;
            if (count > 1) {
                write = writeCount(chars, write, count);
            }
        }
        return write;
    }

    private int writeCount(char[] chars, int write, int count) {
        int divisor = 1;
        while (divisor <= count / 10) {
            divisor *= 10;
        }
        while (divisor > 0) {
            chars[write++] = (char) ('0' + count / divisor);
            count %= divisor;
            divisor /= 10;
        }
        return write;
    }
}

