            while (read < chars.length && chars[read] == current) {
                read++;
            }

            chars[write++] = current;
            int count = read - start;
            if (count > 1) {
                write = writeCount(chars, write, count);
            }
        }
        return write;
    }

    private int writeCount(char[] chars, int write, int count) {
        if (count >= 10) {
            write = writeCount(chars, write, count / 10);
        }
        chars[write++] = (char) ('0' + count % 10);
        return write;
    }
}

class Solution {
    public int compress(char[] chars) {
        int write = 0;
        int groupStart = 0;
        for (int read = 0; read <= chars.length; read++) {
            if (read == chars.length || chars[read] != chars[groupStart]) {
                chars[write++] = chars[groupStart];
                int count = read - groupStart;
                if (count > 1) {
                    write = writeCount(chars, write, count);
                }
                groupStart = read;
            }
        }
        return write;
    }

    private int writeCount(char[] chars, int write, int count) {
        int divisor = 1;
        while (divisor <= count / 10) {
            divisor *= 10;
        }
        while (divisor > 0) {
            chars[write++] = (char) ('0' + count / divisor);
            count %= divisor;
            divisor /= 10;
        }
        return write;
    }
}
